function shortFirst(words) {
  return [words.filter((w) => w.length < 5), words.filter((w) => w.length >= 5)];
}

function evensThenOdds(numbers) {
  return [numbers.filter((n) => n % 2 === 0), numbers.filter((n) => n % 2 !== 0)];
}

